48	function getFactualityScoreLookup(grading: GradingConfig): Record<string, number> {
49	  return {
50	    A: grading.factuality?.subset ?? 1,
51	    B: grading.factuality?.superset ?? 1,
52	    C: grading.factuality?.agree ?? 1,
53	    D: grading.factuality?.disagree ?? 0,
54	    E: grading.factuality?.differButFactual ?? 1,
55	  };
