1	import { isGraderFailure, matchesGEval } from '../matchers/llmGrading';
2	import invariant from '../util/invariant';
3	import { accumulateTokenUsage, createEmptyTokenUsage } from '../util/tokenUsageUtils';
4	
5	import type { AssertionParams, GradingResult } from '../types/index';
6	
7	type MatcherResponse = Awaited<ReturnType<typeof matchesGEval>>;
8	
9	export const handleGEval = async ({
10	  assertion,
11	  inverse,
12	  renderedValue,
13	  prompt,
14	  outputString,
15	  test,
16	  providerCallContext,
17	}: AssertionParams): Promise<GradingResult> => {
18	  invariant(
19	    typeof renderedValue === 'string' ||
20	      (Array.isArray(renderedValue) && renderedValue.every((value) => typeof value === 'string')),
21	    'G-Eval assertion type must have a string or array of strings value',
22	  );
23	
24	  const threshold = assertion.threshold ?? 0.7;
25	
26	  if (Array.isArray(renderedValue)) {
27	    if (renderedValue.length === 0) {
28	      return {
29	        assertion,
30	        pass: false,
31	        score: 0,
32	        reason: 'G-Eval assertion requires at least one criterion string in the value array.',
33	      };
34	    }
35	
36	    // Evaluate criteria serially so we can short-circuit on the first grader
37	    // failure — a grader transport/parse failure is propagated verbatim without
38	    // inversion, and continuing to spend grader calls on the remaining criteria
39	    // would be wasted API cost.
40	    const responses: MatcherResponse[] = [];
41	    let failure: { index: number; resp: MatcherResponse } | undefined;
42	    for (const [index, value] of renderedValue.entries()) {
43	      const resp = await matchesGEval(
44	        value,
45	        prompt || '',
46	        outputString,
47	        threshold,
48	        test.options,
49	        providerCallContext,
50	      );
51	      responses.push(resp);
52	      if (isGraderFailure(resp)) {
53	        failure = { index, resp };
54	        break;
55	      }
56	    }
57	
58	    const tokensUsed = createEmptyTokenUsage();
59	    for (const r of responses) {
60	      accumulateTokenUsage(tokensUsed, r.tokensUsed);
61	    }
62	
63	    if (failure) {
64	      const criterion = renderedValue[failure.index];
65	      return {
66	        assertion,
67	        pass: false,
68	        score: 0,
69	        reason: `G-Eval criterion ${failure.index + 1}/${renderedValue.length} (${JSON.stringify(criterion)}) failed: ${failure.resp.reason}`,
70	        tokensUsed,
71	        metadata: failure.resp.metadata,
72	      };
73	    }
74	
75	    const averageScore = responses.reduce((acc, r) => acc + r.score, 0) / responses.length;
76	    const combinedReason = responses.map((r) => r.reason).join('\n\n');
77	    const passed = averageScore >= threshold !== inverse;
78	
79	    return {
80	      assertion,
81	      pass: passed,
82	      score: inverse ? 1 - averageScore : averageScore,
83	      reason: combinedReason,
84	      tokensUsed,
85	    };
86	  }
87	
88	  const resp = await matchesGEval(
89	    renderedValue,
90	    prompt || '',
91	    outputString,
92	    threshold,
93	    test.options,
94	    providerCallContext,
95	  );
96	
97	  if (isGraderFailure(resp)) {
98	    return {
99	      assertion,
100	      pass: false,
101	      score: 0,
102	      reason: resp.reason,
103	      tokensUsed: resp.tokensUsed,
104	      metadata: resp.metadata,
105	    };
106	  }
107	
108	  const passed = resp.score >= threshold !== inverse;
109	
110	  return {
111	    assertion,
112	    ...resp,
113	    pass: passed,
114	    score: inverse ? 1 - resp.score : resp.score,
115	  };
