36	export async function loadRubricPrompt(
37	  rubricPrompt: string | object | undefined,
38	  defaultPrompt: string,
39	): Promise<string> {
40	  if (!rubricPrompt) {
41	    return defaultPrompt;
42	  }
43	
44	  if (typeof rubricPrompt === 'object' && Object.keys(rubricPrompt).length === 0) {
45	    return defaultPrompt;
46	  }
47	
48	  if (typeof rubricPrompt === 'string' && rubricPrompt.startsWith('file://')) {
49	    const basePath = cliState.basePath || '';
50	
51	    // Render Nunjucks templates in the file path (e.g., file://{{ env.RUBRIC_PATH }}/rubric.json)
52	    const renderedFilePath = getNunjucksEngineForFilePath().renderString(rubricPrompt, {});
53	
54	    // Parse the file URL to extract file path and function name
55	    // This handles colon splitting correctly, including Windows drive letters and :functionName suffix
56	    const { filePath, functionName } = parseFileUrl(renderedFilePath);
57	    const resolvedPath = path.resolve(basePath, filePath);
58	
59	    if (isJavascriptFile(filePath)) {
60	      rubricPrompt = await loadFromJavaScriptFile(resolvedPath, functionName, []);
61	    } else {
62	      // For non-JS files (including .json, .yaml, .txt), load as raw text
63	      // to allow Nunjucks templating before JSON/YAML parsing.
64	      // This fixes the issue where .json files with Nunjucks templates
65	      // would fail to parse before rendering.
66	      try {
67	        rubricPrompt = await fs.readFile(resolvedPath, 'utf8');
68	      } catch (error) {
69	        if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
70	          throw new Error(`File does not exist: ${resolvedPath}`);
71	        }
72	        throw error;
73	      }
74	    }
75	  } else {
76	    // Load from external file if needed (for non file:// references)
77	    rubricPrompt = maybeLoadFromExternalFile(rubricPrompt);
78	  }
79	
80	  if (typeof rubricPrompt === 'object') {
81	    rubricPrompt = JSON.stringify(rubricPrompt);
82	  }
83	
84	  invariant(typeof rubricPrompt === 'string', 'rubricPrompt must be a string');
85	  return rubricPrompt;
86	}
