88	function processContextForTemplating(
89	  context: Record<string, VarValue>,
90	  enableObjectAccess: boolean,
91	): Record<string, VarValue> {
92	  if (enableObjectAccess) {
93	    return context;
94	  }
95	
96	  return Object.fromEntries(
97	    Object.entries(context).map(([key, value]) => {
98	      if (value && typeof value === 'object') {
99	        if (Array.isArray(value)) {
100	          return [
101	            key,
102	            value.map((item) => (item && typeof item === 'object' ? JSON.stringify(item) : item)),
103	          ];
104	        }
105	        return [key, JSON.stringify(value)];
106	      }
107	      return [key, value];
108	    }),
109	  );
110	}
